def _check_delimiter(delimiter):
    """Rule 9: delimiter is exactly one character, not '"', '\\n' or '\\r'."""
    if not isinstance(delimiter, str) or len(delimiter) != 1:
        raise ValueError("delimiter must be exactly one character")
    if delimiter in ('"', "\n", "\r"):
        raise ValueError("delimiter must not be a quote, \\n or \\r")


def parse_record(text, delimiter=","):
    """Split one delimited record into its fields. See TASK.md."""
    _check_delimiter(delimiter)
    n = len(text)
    fields = []
    i = 0
    while True:
        if i < n and text[i] == '"':
            # Rule 2: quoted field.
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise ValueError("quoted field is not closed")
                c = text[i]
                if c == '"':
                    if i + 1 < n and text[i + 1] == '"':
                        buf.append('"')
                        i += 2
                        continue
                    i += 1  # closing quote
                    break
                buf.append(c)
                i += 1
            fields.append("".join(buf))
            # Rule 3: after the closing quote comes the delimiter or the end.
            if i == n:
                return fields
            if text[i] != delimiter:
                raise ValueError("text after closing quote must be a delimiter or end")
            i += 1
        else:
            # Rule 4 and 5: unquoted field.
            j = i
            while j < n and text[j] != delimiter:
                if text[j] in ('"', "\n", "\r"):
                    raise ValueError("invalid character in unquoted field")
                j += 1
            fields.append(text[i:j])
            if j == n:
                return fields
            i = j + 1


def format_record(fields, delimiter=","):
    """Write fields as one delimited record. See TASK.md."""
    _check_delimiter(delimiter)
    try:
        fields = list(fields)
    except TypeError:
        raise ValueError("fields must be a sequence of str")
    # Rule 7: at least one field, and every field a str.
    if not fields:
        raise ValueError("at least one field is required")
    out = []
    for f in fields:
        if not isinstance(f, str):
            raise ValueError("every field must be a str")
        # Rule 6: quote when containing delimiter, '"', '\n', '\r', or
        # starting/ending with a space.
        needs_quotes = (
            delimiter in f
            or '"' in f
            or "\n" in f
            or "\r" in f
            or f.startswith(" ")
            or f.endswith(" ")
        )
        if needs_quotes:
            out.append('"' + f.replace('"', '""') + '"')
        else:
            out.append(f)
    return delimiter.join(out)
